export async function cleanupHandoff(runFile,runSha256){const {run,task}=await load(runFile,runSha256);assertHandoffIdentity(await handoffIdentity(),run.identity,{afterLogon:run.afterLogon});const status=await handoffStatus(runFile,runSha256);assert.equal(status.nativeCompleted,true,'Unknown/unfinished task is preserved');const current=await readHandoffTask(task.name);if(!current)return {status:'already-removed',evidencePreserved:true};assertHandoffTaskSecurity(current.security,run.identity.sid);assert.equal(current.state,3);assert.equal(current.instances,0);await ps(taskPrelude+taskProjection+taskSecurityProjection+String.raw`$t=$f.GetTask($v.name);AssertTaskSecurity $t $v.definition.userId;if(-not(Equal (Project $t.Definition) $v.definition)){throw 'Task ownership drifted before cleanup'};if([int]$t.State -ne 3 -or [int]$t.GetInstances(0).Count -ne 0){throw 'Task active during cleanup'};$f.DeleteTask($v.name,0);'true'`,task);assert.equal(await readHandoffTask(task.name),null);return {status:'task-removed',evidencePreserved:true};}
async function main(){const {values:v}=parseArgs({strict:true,allowPositionals:false,options:{action:{type:'string'},config:{type:'string'},phase:{type:'string'},dispatch:{type:'string'},'intent-sha':{type:'string'},materials:{type:'string'},'material-sha':{type:'string'},'after-logon':{type:'boolean'},run:{type:'string'},'run-sha':{type:'string'}}});assert.ok(['prepare','register','run','status','cleanup','execute'].includes(v.action));if(v.action==='prepare'){assert.equal(v.run,undefined);assert.equal(v['run-sha'],undefined);console.log(JSON.stringify(await prepareHandoff({configFile:v.config,phase:v.phase,dispatchId:v.dispatch,intentSha256:v['intent-sha'],materials:v.materials,materialSha256:v['material-sha'],afterLogon:v['after-logon']})));return;}assert.deepEqual(Object.keys(v).sort(),['action','run','run-sha']);const fn={register:registerHandoff,run:startHandoff,status:handoffStatus,cleanup:cleanupHandoff,execute:executeHandoff}[v.action],result=await fn(v.run,v['run-sha']);if(v.action==='execute'){process.exitCode=result.exitCode;return;}console.log(JSON.stringify(result));}
if(process.argv[1]&&same(process.argv[1],ownFile))main().catch(e=>{console.error(JSON.stringify({status:'handoff-refused',error:e.message}));process.exitCode=1;});
